func NewResolver(
	httpClient *http.Client,
	logger *zap.Logger,
	zoneRepositoryFactory repository.ZoneRepositoryFactory,
	rrSetRepositoryFactory repository.RRSetRepositoryFactory,
	secretFetcher SecretFetcher,
	configProvider ConfigProvider,
